/*
 * epd_deco_font.h - Art Deco numerals for the clock face.
 *
 * Digits only: the dial is the one place that needs them, and the built-in 5x7
 * font in epd_paint.c still serves everything else. The glyphs are bitmaps
 * generated by tools/make_deco_font.py from a geometric construction -- ellipse
 * rings, slabs and diagonals with a heavy flank against a light crown -- so
 * they are edited by changing that script and running it again, not by hand.
 *
 * Fixed size, because they are drawn at the size the dial needs. Scaling a
 * bitmap this detailed would only wreck the stroke contrast that makes it Deco.
 */
#pragma once

#include <stdint.h>

#define DECO_GLYPH_H 44   /* every figure is full height; there are no descenders */

/*
 * One row per word, leftmost pixel in bit 0. Glyphs are trimmed to their ink
 * and carry their own width, so numerals are set proportionally -- a 1 takes
 * the width of its slab and nothing more.
 */
typedef struct {
    uint8_t w;
    uint32_t rows[DECO_GLYPH_H];
} deco_glyph_t;

extern const deco_glyph_t DECO_DIGITS[10];
